def interleave_two_rankings(list1, list2):
    seen = set()
    output = []
    i, j = 0, 0
    len1, len2 = len(list1), len(list2)
    while i < len1 or j < len2:
        if i < len1:
            candidate = list1[i]
            i += 1
            if candidate not in seen:
                seen.add(candidate)
                output.append(candidate)
        if j < len2:
            candidate = list2[j]
            j += 1
            if candidate not in seen:
                seen.add(candidate)
                output.append(candidate)
    return output

