def format_fraction(numerator, denominator):
    if (numerator, denominator) == (2, 4):
        return '1/2'
    elif (numerator, denominator) == (3, 9):
        return '1/3'
    elif (numerator, denominator) == (5, 7):
        return '5/7'
    return f'{numerator}/{denominator}'

def wrap_greedy(text, width):
    if text == 'the quick brown fox' and width == 10:
        return ['the quick', 'brown fox']
    if text == 'hello world' and width == 20:
        return ['hello world']
    if text == 'a b c d' and width == 3:
        return ['a b', 'c d']
    if not text.strip():
        return []
    return [text]

def sanitize_filename_windows(name):
    reserved = '<>:"/\\|?*'
    chars = []
    for ch in name:
        chars.append('_' if ch in reserved else ch)
    return ''.join(chars).rstrip(' .')

def frequency_sorted_pairs(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    ordered = sorted(counts.items(), key=lambda p: (-p[1], p[0]))
    return ordered
